pub fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    debug_assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    let mut result = Vec::with_capacity(a.len());
    for (x, y) in a.into_iter().zip(b.into_iter()) {
        result.push(x <= y);
    }
    result
}